// Generated by Cypress Author — 2026-11-17.
// Contract: QA/Test-Cases/EZPOST_QA_AUTHENTICATED_SESSION_TEST_CASES.md.
// One independent journey per browser. Phone/OTP input is MANUAL-ASSISTED setup.
import { liveAuthentication } from '../../support/authenticated-session-runtime';

const sessionPath = '/api/v1/auth/session';
const cartPath = '/api/v1/cart';
const manualEntryLimit = 30 * 60 * 1000; // Human handoff window, not application latency.

function realSession(checkName, reload = false) {
  const auth = liveAuthentication();
  return cy.request({ method: 'GET', url: sessionPath, log: false, failOnStatusCode: false }).then(response => {
    const valid = response.status === 200 && auth.matchesSession(response.body?.user);
    auth.check(checkName, valid && (!reload || auth.sameSession(response.body?.user)));
    if (!reload) auth.rememberSession(response.body.user);
  });
}

function cartIntent(items) {
  return items.map(item => JSON.stringify([item.id, item.product_slug, item.package_id,
    item.artwork_id, item.quantity])).sort().join('|');
}

describe('Manual ordinary sign-in followed by real authenticated checks', () => {
  it('AUTH-SESSION01 — designated ordinary identity renders correctly and survives read-only shopping inspection', () => {
    const auth = liveAuthentication();
    let initialCartIntent;
    cy.intercept('GET', sessionPath).as('initialGuest');
    cy.visit('/cart');
    cy.wait('@initialGuest', { log: false }).then(({ response }) => {
      auth.check('freshGuestBeforeManualLogin', response?.statusCode === 200 &&
        Object.hasOwn(response.body || {}, 'user') && response.body.user === null);
    });
    cy.get('main [data-cy="cart-item"]').should('not.exist');
    cy.get('main .commerce-empty').should('have.length', 1).and('be.visible');
    cy.window({ log: false }).then(win => {
      const raw = win.localStorage.getItem('ezpost_guest_cart_v1');
      // Source key/shape observed in the public guest-storage module. Read only.
      const empty = raw === null || (Array.isArray(JSON.parse(raw)) && JSON.parse(raw).length === 0);
      auth.check('guestSyncStorageIsActuallyEmpty', empty);
    });
    cy.then(() => auth.check('guestCartEmptyBeforeSync', true));
    cy.get('header a[aria-label="حساب کاربری"]').should('have.length', 1)
      .and('have.attr', 'href', '/login').and('be.visible').click();
    cy.location('pathname').should('eq', '/login');
    cy.get('main [data-cy="login-form"] #mobile').should('be.visible').and('have.value', '');
    cy.then(() => auth.phase('awaiting-phone', '/login'));

    // Passive handoff: only the user's real form actions can resolve this gate.
    // No cy.type(), synthetic submit, success response, copied session or bypass.
    cy.then({ timeout: manualEntryLimit }, () => auth.waitForVerification()).then(result => {
      auth.check('manualVerificationReturnedSuccessStatus', result.succeeded);
      auth.check('exactlyOneManualStartAndVerify', auth.status.otpStartCount === 1 && auth.status.otpVerifyCount === 1);
    });

    cy.then(() => auth.phase('checking-session'));
    realSession('sessionMatchesDesignatedOrdinaryIdentity');
    cy.request({ method: 'GET', url: '/api/v1/auth/me', log: false, failOnStatusCode: false }).then(response => {
      auth.check('meMatchesDesignatedOrdinaryIdentity', response.status === 200 && auth.matchesMe(response.body));
    });
    cy.get('header a[aria-label="حساب کاربری"]').should('have.length', 1)
      .and('have.attr', 'href', '/account').and('be.visible');
    cy.location('pathname').then(pathname => auth.phase('checking-rendered-account', pathname));
    // Follow the explicit account link. The earlier landing path is observation,
    // not approval of fallback/next or cart-merge business policy.
    cy.get('header a[aria-label="حساب کاربری"]').click();
    cy.location('pathname').should('eq', '/account');
    cy.get('main .account-dashboard').should('have.length', 1).and('be.visible');
    cy.get('section.account-card[aria-label="مشخصات حساب"] .account-mobile')
      .should('have.length', 1).and('be.visible').should($element => {
        auth.check('renderedAccountMatchesDesignatedIdentity', auth.matchesDisplayedMobile($element.text()));
      });
    cy.get('section.account-card[aria-label="مشخصات حساب"] .account-role-badge')
      .should('have.length', 1).and('be.visible').and('have.text', 'مشتری');
    cy.then(() => auth.check('renderedRoleIsOrdinaryCustomer', true));

    cy.then(() => auth.phase('checking-reload', '/account'));
    cy.intercept('GET', sessionPath).as('reloadedIdentity');
    cy.reload();
    cy.wait('@reloadedIdentity', { log: false }).then(({ response }) => {
      auth.check('reloadKeepsExactOrdinaryIdentity', response?.statusCode === 200 && auth.sameSession(response.body?.user));
    });
    cy.get('main .account-dashboard').should('be.visible');
    cy.get('section.account-card[aria-label="مشخصات حساب"] .account-mobile').should($element => {
      auth.check('reloadedInterfaceMatchesIdentity', auth.matchesDisplayedMobile($element.text()));
    });
    realSession('reloadSessionConfirmedReadOnly', true);

    cy.then(() => auth.phase('checking-cart', '/cart'));
    cy.intercept('GET', cartPath).as('authenticatedCart');
    cy.visit('/cart');
    cy.wait('@authenticatedCart', { log: false }).then(({ response }) => {
      auth.check('realAuthenticatedCartResponseHasItems', response?.statusCode === 200 && Array.isArray(response.body?.items));
      initialCartIntent = cartIntent(response.body.items); // Private snapshot; never persisted.
      cy.get('main [data-cy="cart-item"]').should('have.length', response.body.items.length);
      if (response.body.items.length === 0) cy.get('main .commerce-empty').should('be.visible');
      else cy.get('main .cart-items').should('be.visible');
    });
    realSession('cartStillUsesIntendedOrdinaryIdentity', true);

    cy.then(() => auth.phase('checking-customer'));
    cy.window({ log: false }).then(win => {
      // Do not restore or clear an address/order draft. A complete restored
      // address can automatically trigger a shipping POST outside this slice.
      const safeToInspect = !win.sessionStorage.getItem('ezpost_checkout_address') &&
        !win.sessionStorage.getItem('ezpost_active_order_id');
      auth.status.checks.customerInspectionSafeWithoutRestoration = safeToInspect;
      if (!safeToInspect) {
        auth.status.checks.customerInspectionDeferred = true;
        auth.phase('checking-customer');
        return;
      }
      cy.intercept('GET', cartPath).as('customerScreenCart');
      cy.visit('/checkout'); // No order query, field entry, submit or payment.
      cy.wait('@customerScreenCart', { log: false }).then(({ response }) => {
        auth.check('customerInspectionDoesNotChangeCartIntent', response?.statusCode === 200 &&
          Array.isArray(response.body?.items) && cartIntent(response.body.items) === initialCartIntent);
      });
      cy.get('main').should('be.visible');
      // Inspect only booleans. Empty-cart routing/form eligibility is not an
      // approved acceptance rule; no assertion chooses a policy here.
      cy.document({ log: false }).then(doc => {
        auth.status.checks.customerFormObserved = Boolean(doc.querySelector('main form[data-cy="checkout-form"]'));
        auth.status.checks.customerInspectionDeferred = false;
        auth.phase('checking-customer', doc.location.pathname);
      });
    });

    realSession('finalSessionStillMatchesDesignatedIdentity', true);
    cy.request({ method: 'GET', url: cartPath, log: false, failOnStatusCode: false }).then(response => {
      auth.check('preExistingCartIntentPreserved', response.status === 200 &&
        Array.isArray(response.body?.items) && cartIntent(response.body.items) === initialCartIntent);
      auth.check('noForbiddenMutationAttempted', auth.status.blockedMutations === 0);
      auth.phase('completed');
    });
  });
});
